// Gabarit Accueil, envoi : les conditions de lib-boite-envoyer et de lib/pilote/regles.ts, rejouees avant toute reponse. Un doute vaut un refus.
const cfg = $('Lire les réglages').first().json || {};
const org = $('Compte de cette copie').first().json.organisation_id;
const simulation = cfg.simulation !== false;
const maintenant = cfg.maintenant ? Date.parse(cfg.maintenant) : Date.now();
const cap = cfg.capacites || [];
const autonome = cap.indexOf('plateforme.ia.auto') >= 0 && cap.indexOf('assistant.pilote') >= 0;
const pilote = cfg.pilote || {};
const coupe = cfg.interrupteur_general === false || cfg.interrupteur_departement === false;
const DIX_MIN = 600000;
const JOUR = 86400000;
const CANAUX = ['gmail', 'outlook', 'imap', 'whatsapp', 'telegram', 'messenger', 'instagram'];
let partis = Number(cfg.parties_depuis_24h || 0);
const plafond = Number(cfg.plafond_jour || 0);
const sortie = [];
for (const it of $input.all()) {
  const l = it.json;
  const age = maintenant - Date.parse(l.prete_le);
  let decision = 'envoyer';
  let motif = null;
  if (coupe) motif = 'interrupteur';
  else if (!autonome) motif = 'offre';
  else if (cfg.mode_reponse !== 'auto') motif = 'mode';
  else if (!(pilote.drapeau && pilote.actif)) motif = 'pilote';
  else if (l.type !== 'reponse_prospect') motif = 'type_action';
  else if (!(pilote.types && pilote.types.reponse_prospect === true)) motif = 'type';
  else if (l.opposition !== false) motif = 'opposition';
  else if (CANAUX.indexOf(l.canal_origine) < 0) motif = 'canal_non_branche';
  else if (!(age >= 0) || age > JOUR) motif = 'perime';
  else if (age < DIX_MIN) { decision = 'attendre'; motif = 'delai_10_minutes'; }
  else if (partis >= plafond) motif = 'plafond';
  if (!motif) partis += 1;
  else if (decision !== 'attendre') decision = 'repli';
  sortie.push({ json: Object.assign({}, l, { organisation_id: org, simulation: simulation, decision: decision, motif: motif, marque_artisan: cfg.marque_artisan }) });
}
return sortie;

// Simulation : rien ne part ; les envois prevus sont listes. Studio n'envoie jamais (decision repli, motif offre).
const prevus = [];
for (const it of $input.all()) {
  const l = it.json;
  if (l.decision === 'envoyer') prevus.push({ effet: 'envoyer_' + l.canal_origine, action: l.id });
  else if (l.decision === 'repli') prevus.push({ effet: 'repasser_en_carte', action: l.id, motif: l.motif });
  else prevus.push({ effet: 'attendre', action: l.id, motif: l.motif });
}
return [{ json: { simulation: true, effets_prevus: prevus, effets_faits: [] } }];

